/**
 * Registry metadata sanity: paths referenced by the marketplace entry must exist.
 *
 * The entry once pointed at `icons/dsh-doc-ledger.svg`, a file that never existed in this
 * repository (the real artwork is `docs/icon.svg` / `docs/icon-512.png`), so a market page
 * would have shown a broken icon. Versions are generated by the marketplace script, so only
 * the paths are asserted here.
 */
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const entry = JSON.parse(readFileSync(join(root, "docs", "plugin-registry-entry.json"), "utf8"));

const cases = [];
function check(name, body) { cases.push([name, body]); }

check("registry 条目的 icon 路径真实存在", () => {
  assert.equal(typeof entry.icon, "string");
  assert.ok(existsSync(join(root, entry.icon)), entry.icon + " 不存在");
});

check("registry 条目指向的 README 与 package.json 版本可读", () => {
  const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
  assert.equal(entry.name, pkg.name);
  assert.equal(entry.repository.url, pkg.repository.url.replace(/^git\+/, "").replace(/\.git$/, ""));
});

check("awesome 列表条目的图标是托管位图而不是 SVG", () => {
  const yml = readFileSync(join(root, "docs", "awesome-plugin-entry.yml"), "utf8");
  const m = yml.match(/^icon:\s*(\S+)$/m);
  assert.ok(m, "awesome 条目必须声明 icon");
  assert.match(m[1], /\.(png|jpe?g|webp|gif)$/i, "awesome 列表拒收 SVG，必须是位图");
});

for (const [name, body] of cases) {
  body();
  console.log("  · " + name);
}
console.log("ok - " + cases.length + " registry checks");
